using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.CostCenters.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.CostCenters.Queries.GetCostCenterById;public sealed class GetCostCenterByIdQueryHandler(ICostCenterRepository repository):IRequestHandler<GetCostCenterByIdQuery,Result<CostCenterDto>>{public async Task<Result<CostCenterDto>>Handle(GetCostCenterByIdQuery request,CancellationToken cancellationToken){var e=await repository.FindByIdAsync(request.Id,cancellationToken);return e is null?Result.Failure<CostCenterDto>(CostCenterErrors.NotFound):Result.Success(CostCenterDto.FromEntity(e));}}
